fn solve(n: i8) -> bool {
    // Since n is i8, we need to work with its absolute value
    // and extract digits from the 4-digit representation
    let n_abs = n.unsigned_abs() as u32;
    
    // Extract individual digits
    let thousands = (n_abs / 1000) % 10;
    let hundreds = (n_abs / 100) % 10;
    let tens = (n_abs / 10) % 10;
    let ones = n_abs % 10;
    
    // Check if first three digits are equal
    let first_three_equal = (thousands == hundreds) && (hundreds == tens);
    
    // Check if last three digits are equal
    let last_three_equal = (hundreds == tens) && (tens == ones);
    
    first_three_equal || last_three_equal
}